// EditorService_NewServer creates a new Server from an implementation of EditorService_Server.
func EditorService_NewServer(s EditorService_Server) *server.Server {
	c, _ := s.(server.Shutdowner)
	return server.New(EditorService_Methods(nil, s), s, c)
}

// EditorService_ServerToClient creates a new Client from an implementation of EditorService_Server.
// The caller is responsible for calling Release on the returned Client.
func EditorService_ServerToClient(s EditorService_Server) EditorService {
	return EditorService(capnp.NewClient(EditorService_NewServer(s)))
}

